const s=input.state,e=input.event;
if(e.type==='preview'||e.type==='render')return {state:input.state};
function pad(n){return n<10?'0'+n:String(n);}
function fmt(ms){let v=Math.floor(Number(ms)/100);if(!isFinite(v)||v<0)v=0;const t=v%10;const secs=Math.floor(v/10);const sec=secs%60;const mins=Math.floor(secs/60);const min=mins%60;const hr=Math.floor(mins/60);return pad(hr)+':'+pad(min)+':'+pad(sec)+'.'+t;}
if(e.type==='action'){
 const a=e.actionId;
 if(a==='start'&&!s.running){s.startAt=Date.now();s.running=true;}
 else if(a==='stop'&&s.running){s.elapsedMs=Math.max(0,Date.now()-s.startAt);s.startAt=0;s.running=false;}
 else if(a==='reset'){s.running=false;s.startAt=0;s.elapsedMs=0;s.laps=[];s.nextLap=1;s.lastLapMs=0;}
 else if(a==='lap'&&s.running){
  const total=Math.max(0,Date.now()-s.startAt);
  const split=Math.max(0,total-s.lastLapMs);
  s.laps.push({id:'l'+s.nextLap,name:'Lap '+s.nextLap,split:fmt(split),total:fmt(total)});
  while(s.laps.length>50)s.laps.shift();
  s.lastLapMs=total;s.nextLap=s.nextLap+1;
 }
}
if(s.running&&s.startAt>0)s.elapsedMs=Math.max(0,Date.now()-s.startAt);
s.elapsedText=fmt(s.elapsedMs);
s.statusText=s.running?'Running':(s.elapsedMs>0?'Paused':'Ready');
s.lapCountText=String(s.laps.length);
s.hasLaps=s.laps.length>0;s.noLaps=!s.hasLaps;s.notRunning=!s.running;
s.canReset=s.elapsedMs>0||s.laps.length>0;
const commands=[{type:'circle',x:32,y:32,radius:22,color:s.running?'accent':'muted'},{type:'circle',x:32,y:32,radius:13,color:'default'}];
const out={state:s,surfaces:{ticker:{commands:commands}}};
if(e.type==='action'||e.type==='open'||e.type==='timer')out.timers=s.running?[{id:'tick',intervalMs:100}]:[];
return out;
